import {PropsWithChildren} from "react";
import {AnyText, SurveyItemVM} from "./model";
import {Translated} from "./translated";

type Props = PropsWithChildren<{
    item: SurveyItemVM,
    questionText: AnyText,
    layout: "2-rows" | "2-columns"
}>

function BaseSurveyItem({item, questionText, layout, children}: Props) {
    const classes = `block_coursefeedback-surveyitem block_coursefeedback-${item.type}`;

    return <div className={classes}>
        <div className="question-area coursefeedback-questiontext">
            <Translated text={questionText}/>
        </div>

        <div className="answer-area">

        </div>
    </div>
}